-- Privileges of the database roles on the kernel tables (spec 03 section 3.7; CR-004)

-- Group roles are created here only where the migrating login may create roles (a fresh server or a test);
-- provisioning creates them before the first migration, so a customer's owner login never needs that right.
do $do$ begin
    if not exists (select 1 from pg_roles where rolname = 'app_rw') then create role app_rw nologin; end if;
    if not exists (select 1 from pg_roles where rolname = 'app_ro') then create role app_ro nologin; end if;
    if not exists (select 1 from pg_roles where rolname = 'app_audit') then create role app_audit nologin; end if;
    if not exists (select 1 from pg_roles where rolname = 'backup') then create role backup nologin; end if;
end $do$;

